+/**
+ * Function: isValidColor
+ *
+ * Returns true if the given value is a valid CSS color string.
+ * This prevents XSS by ensuring color values cannot contain
+ * HTML attributes or JavaScript code.
+ *
+ * Parameters:
+ * color - The color value to validate.
+ */
+mxUtils.isValidColor = function(color)
+{
+	if (color == null || color.length == 0)
+	{
+		return false;
+	}
+	
+	// Hex colors: #RGB, #RRGGBB, #RRGGBBAA
+	if (/^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})$/.test(color))
+	{
+		return true;
+	}
+	
+	// rgb/rgba/hsl/hsla with numeric values only
+	if (/^(rgb|hsl)a?\(\s*[\d.]+%?\s*,\s*[\d.]+%?\s*,\s*[\d.]+%?\s*(,\s*[\d.]+%?\s*)?\)$/i.test(color))
+	{
+		return true;
+	}
+	
+	// Named colors: alphabetic only (unknown names safely ignored by browsers)
+	if (/^[a-zA-Z]+$/.test(color))
+	{
+		return true;
+	}
+	
+	return false;
+};

